function model(p) {
  // One illustrative professional claim moving through a generic health plan's claims process.
  // Event times are playback seconds for the explainer, not real processing times. Amounts are illustrative.
  const pa = Math.max(0, Math.min(2, Math.round(p.priorAuth)));   // 0 not needed, 1 approved, 2 missing
  const info = Math.round(p.missingInfo) === 1;
  const ap = Math.max(0, Math.min(2, Math.round(p.appeal)));      // 0 none filed, 1 won, 2 lost
  const lanes = [
    { id: 'provider', label: 'Provider' }, { id: 'payer', label: 'Payer system' },
    { id: 'processor', label: 'Claims processor' }, { id: 'member', label: 'Member' }
  ];
  const stations = [
    { id: 'intake', n: 1, lane: 'provider', label: 'Intake', detail: 'The provider\'s billing office sends the claim electronically. The system checks format, member ID and required fields before accepting it.' },
    { id: 'eligibility', n: 2, lane: 'payer', label: 'Eligibility', detail: 'Was the member covered on the date of service, and under which benefits? An inactive member is rejected here, before any review.' },
    { id: 'auth', n: 3, lane: 'payer', label: 'Prior auth', detail: 'Some services must be approved before they happen. The system looks for an authorization matching member, provider, service and dates.' },
    { id: 'adjudicate', n: 4, lane: 'processor', label: 'Adjudication', detail: 'The processor applies benefits, contract pricing, coding edits and the authorization status, then decides: pay, pend or deny.' },
    { id: 'pend', n: 5, lane: 'provider', label: 'Pend: request info', detail: 'A pended claim is on hold, not denied. The payer asks the provider for the missing records and resumes when they arrive.' },
    { id: 'deny', n: 6, lane: 'processor', label: 'Denial', detail: 'A denial must give the reason and the appeal rights. Here the reason is a missing prior authorization.' },
    { id: 'appeal', n: 7, lane: 'member', label: 'Appeal', detail: 'The member or provider asks for reconsideration. A different reviewer weighs the medical evidence and overturns or upholds the denial.' },
    { id: 'pay', n: 8, lane: 'payer', label: 'Payment', detail: 'The plan pays its share (allowed amount minus the member\'s cost share) to the provider in a payment run, with a remittance advice.' },
    { id: 'notify', n: 9, lane: 'member', label: 'EOB to member', detail: 'The member receives an Explanation of Benefits: billed, allowed, paid and what they owe. It is not a bill.' }
  ];
  const edges = [
    ['intake', 'eligibility', ''], ['eligibility', 'auth', ''], ['auth', 'adjudicate', ''],
    ['adjudicate', 'pend', 'request info'], ['pend', 'adjudicate', 'records sent'],
    ['adjudicate', 'pay', 'pay'], ['adjudicate', 'deny', 'no auth'],
    ['deny', 'appeal', 'appeal'], ['deny', 'notify', 'no appeal'],
    ['appeal', 'pay', 'overturned'], ['appeal', 'notify', 'upheld'], ['pay', 'notify', '']
  ].map(([from, to, label]) => ({ id: from + '-' + to, from, to, label }));
  const money = { billed: 1240, allowed: 860, memberShare: 160, planPays: 700 };
  const eligible = true; // assumption: active coverage on the date of service
  const authRequired = pa !== 0;
  const authStatus = ['not required', 'approved', 'missing'][pa];
  const denied = pa === 2;
  const appealFiled = denied && ap !== 0;
  const appealWon = appealFiled && ap === 1;
  const paid = eligible && (!authRequired || pa === 1 || appealWon) && (!denied || appealWon);
  const raw = [];
  const add = (station, kind, note, dur) => raw.push({ station, kind, note, dur });
  add('intake', 'submit', 'The provider submits the claim: member, diagnosis and procedure codes, $' + money.billed + ' billed.', 1.4);
  add('eligibility', 'eligible', 'Coverage is active on the date of service, so the claim moves on.', 1.2);
  add('auth', ['notRequired', 'approved', 'missing'][pa], [
    'This outpatient service does not require prior authorization.',
    'An approved authorization matches the member, provider, service and dates.',
    'The service requires prior authorization, and none is on file.'][pa], 1.4);
  if (info) {
    add('adjudicate', 'pendStart', 'The processor finds the operative report missing and cannot finish adjudication.', 1.3);
    add('pend', 'pend', 'Pended, not denied: the provider is asked for the report and the claim waits.', 1.6);
  }
  add('adjudicate', denied ? 'denyDecision' : 'payDecision', (info ? 'Records arrive and adjudication resumes. ' : '') + (denied
    ? 'Decision: the authorization rule is not met, so no payment.'
    : 'Decision: benefits and pricing allow $' + money.allowed + ' of $' + money.billed + ' billed.'), info ? 1.6 : 1.4);
  if (denied) {
    add('deny', 'deny', 'Denied for missing prior authorization; the notice explains the appeal rights.', 1.3);
    if (appealFiled) add('appeal', appealWon ? 'won' : 'lost', appealWon
      ? 'Appeal won: a reviewer finds the service medically necessary and overturns the denial.'
      : 'Appeal lost: a second reviewer upholds the denial.', 1.6);
  }
  if (paid) add('pay', 'pay', 'The plan pays the provider $' + money.planPays + '; the member\'s share is $' + money.memberShare + '.', 1.4);
  add('notify', paid ? 'eobPaid' : 'eobDenied', paid
    ? 'The member\'s EOB shows $' + money.allowed + ' allowed, $' + money.planPays + ' paid by the plan, $' + money.memberShare + ' owed.'
    : 'The member\'s notice shows $0 paid by the plan, with the denial reason' + (appealFiled ? ' and the appeal decision.' : ' and how to appeal.'), 1.3);
  const total = raw.reduce((a, e) => a + e.dur, 0), k = Math.min(1, 13 / total);
  let t = 0;
  const events = raw.map((e, i) => { const ev = Object.assign({ i, start: +t.toFixed(2) }, e, { dur: +(e.dur * k).toFixed(2) }); t += e.dur * k; return ev; });
  const duration = +t.toFixed(2);
  const finalState = paid ? 'paid' : 'denied';
  const extras = [];
  if (info) extras.push('one pend for missing records');
  if (appealWon) extras.push('a denial overturned on appeal');
  const summary = paid
    ? 'Paid: the plan pays $' + money.planPays + ' and the member owes $' + money.memberShare + (extras.length ? ', after ' + extras.join(' and ') : '') + (ap !== 0 && !denied ? '; nothing was denied, so no appeal.' : '.')
    : 'Denied for missing prior authorization' + (appealFiled ? '; the appeal upheld it' : '; no appeal was filed') + ', so the plan pays $0.';
  return {
    lanes, stations, edges, events, duration, markers: events.map(e => e.start),
    eligible, authRequired, authStatus, denied, appealFiled, appealWon, pends: info ? 1 : 0,
    finalState, paidAmount: paid ? money.planPays : 0, money, summary
  };
}

checkCode:
function check(p) {
  const m = model(p), ev = m.events, ids = new Set(m.stations.map(s => s.id));
  const real = ev.every(e => ids.has(e.station));
  const timed = ev.every((e, i) => i === 0 || e.start > ev[i - 1].start);
  const legal = ev.every((e, i) => i === 0 || m.edges.some(g => g.from === ev[i - 1].station && g.to === e.station));
  const ends = ev[0].station === 'intake' && ev[ev.length - 1].station === 'notify';
  const denyAt = ev.findIndex(e => e.station === 'deny'), appealAt = ev.findIndex(e => e.station === 'appeal');
  const denied = denyAt >= 0, won = appealAt >= 0 && ev[appealAt].kind === 'won';
  const denyOk = denied === (m.authStatus === 'missing');
  const appealOk = appealAt < 0 || (denied && denyAt < appealAt);
  const authOk = !m.authRequired || m.authStatus === 'approved' || won;
  const shouldPay = m.eligible && authOk && (!denied || won);
  const paidOk = (m.finalState === 'paid') === shouldPay && ev.some(e => e.station === 'pay') === shouldPay;
  const pends = ev.filter(e => e.station === 'pend').length, pendOk = pends === (Math.round(p.missingInfo) === 1 ? 1 : 0);
  return {
    pass: real && timed && legal && ends && denyOk && appealOk && paidOk && pendOk,
    detail: ev.length + ' events, each at a real station and a legal next step in time order; eligible, prior auth ' + m.authStatus + ', ' + pends + (pends === 1 ? ' pend, ' : ' pends, ') +
      (denied ? 'denied' + (appealAt >= 0 ? ' then appeal ' + ev[appealAt].kind : ' with no appeal') : 'never denied') + ', so the claim ends ' + m.finalState + ' with $' + m.paidAmount + ' paid.'
  };
}
